    @Test void singleHttpCandidateReachesPublicParseAndAudit() throws Exception {
        String inner="{\"filters\":{\"sex\":\"F\",\"age\":\"35-45\"},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"},{\"field\":\"age\",\"value\":\"35-45\"}],\"unrecognized\":[],\"status\":\"OK\",\"notice\":\"已生成候选条件，尚未应用。\"}";
        AiGatewayLoopbackPeer.Exchange exchange=peer.json(outer(inner));
        JsonNode parsed=parse("女性35-45岁");
        assertEquals("AI",parsed.path("engine").asText());assertTrue(parsed.path("fallbackReason").isNull());
        assertEquals(json.readTree("{\"sex\":\"F\",\"age\":\"35-45\"}"),parsed.path("candidateFilters"));
        assertEquals("已生成候选条件，尚未应用。",parsed.path("notice").asText());
        assertTrue(exchange.received.await(1,TimeUnit.SECONDS));assertTrue(exchange.eof.await(1,TimeUnit.SECONDS));assertEquals(1,peer.requests.get());assertNull(peer.failure.get());
        assertEquals(new TreeSet<>(Arrays.asList("accept","accept-encoding","authorization","connection","content-length","content-type","host","user-agent")),exchange.headers.keySet());assertTrue(exchange.body.length<=16384);assertEquals(Integer.toString(exchange.body.length),exchange.headers.get("content-length"));assertEquals("POST",exchange.method);assertEquals("/chat/completions",exchange.path);
        assertEquals("application/json; charset=utf-8",exchange.headers.get("content-type"));assertEquals("application/json",exchange.headers.get("accept"));assertEquals("Bearer p05b-loopback-key",exchange.headers.get("authorization"));assertEquals("ra-ai-gateway/1",exchange.headers.get("user-agent"));assertEquals("gzip",exchange.headers.get("accept-encoding"));
        JsonNode wire=json.readTree(exchange.body);assertEquals(new TreeSet<>(Arrays.asList("model","messages","stream","temperature","max_tokens","response_format","thinking")),keys(wire));assertEquals("p05b-synthetic-model",wire.path("model").asText());assertFalse(wire.path("stream").asBoolean());assertEquals(0,wire.path("temperature").asInt());assertEquals(1024,wire.path("max_tokens").asInt());assertEquals(json.readTree("{\"type\":\"json_object\"}"),wire.path("response_format"));assertEquals(json.readTree("{\"type\":\"disabled\"}"),wire.path("thinking"));assertEquals(2,wire.path("messages").size());for(JsonNode message:wire.path("messages"))assertEquals(new TreeSet<>(Arrays.asList("role","content")),keys(message));assertEquals("system",wire.path("messages").get(0).path("role").asText());assertEquals("user",wire.path("messages").get(1).path("role").asText());assertEquals("女性35-45岁",wire.path("messages").get(1).path("content").asText());
        byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(wire.path("messages").get(0).path("content").asText().getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder hash=new StringBuilder();for(byte b:digest)hash.append(String.format("%02x",b));assertEquals("e73fb7fedb281e100d4ed6599e5c1030813eb511ee9f7f991098f4bff7100b6a",hash.toString());
        assertEquals(0,observed.selects);assertEquals(0,observed.inserts);auditExited();assertEquals(1,auditCount());Map<String,String> event=auditEvent(auditObserved.lastEventId);assertEquals("AI",event.get("engine"));assertNull(event.get("fallback_reason"));assertEquals("p05b-synthetic-model",event.get("model_version"));assertEquals("dev-parse-ai-prompt-v01",event.get("prompt_version"));assertEquals(parsed.path("meta").path("durationMs").asText(),event.get("duration_ms"));assertFalse(event.toString().contains("35-45岁"));assertFalse(event.toString().contains("p05b-loopback-key"));assertFalse(event.toString().contains("已生成"));
        JsonNode applied=apply(parsed,"{\"sex\":\"M\",\"tx\":\"TNFi\",\"act\":\"high\",\"at\":\"6m\",\"ids\":[\"1\",\"2\",\"7\"]}",null);assertTrue(applied.path("applied").asBoolean());assertTrue(applied.path("filters").path("tx").isNull());assertTrue(applied.path("filters").path("act").isNull());assertEquals("now",applied.path("filters").path("at").asText());assertEquals(json.readTree("[\"1\",\"2\",\"7\"]"),applied.path("filters").path("ids"));
        JsonNode cohort=success("{\"filters\":"+applied.path("filters")+"}");assertEquals(Collections.singletonList("1"),ids(cohort));assertEquals(1,cohort.path("n").asInt());assertEquals(6,cohort.path("studyTotal").asInt());assertEquals(3,cohort.path("submittedUniqueIdsN").asInt());assertEquals(2,cohort.path("effectiveIdsN").asInt());assertEquals(1,cohort.path("activity").path("evalN").asInt());assertEquals(1.0,cohort.path("stats").path("targetRate").asDouble());assertEquals(1,cohort.path("stats").path("evaluable").asInt());assertEquals(2,auditCount());assertEquals(1,peer.requests.get());
        String evidence=System.getenv("RA_P05B_EVIDENCE_DIR");if(evidence!=null){java.nio.file.Path dir=java.nio.file.Paths.get(evidence);java.nio.file.Files.write(dir.resolve("synthetic-wire.json"),exchange.body);java.nio.file.Files.write(dir.resolve("synthetic-headers.json"),json.writeValueAsBytes(exchange.headers));}
    }
    @Test void normalSmokingNoticesFromSameHttpResponseRemainExactAndRequireExplicitApply() throws Exception {
        String partialNotice="仅生成部分候选条件，尚未应用；需明确确认是否只应用这些候选。“吸烟”不在当前支持的筛选字段中。可用问法示例：女性45至65岁；这只是格式示例，不保留原问题的全部要求。";
        String partial="{\"filters\":{\"sex\":\"F\"},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"}],\"unrecognized\":[{\"reason\":\"UNMAPPED_TEXT\",\"count\":2}],\"status\":\"PARTIAL\",\"notice\":"+json.writeValueAsString(partialNotice)+"}";
        AiGatewayLoopbackPeer.Exchange first=peer.json(outer(partial));JsonNode p=parse("女性且吸烟");assertEquals("AI",p.path("engine").asText());assertTrue(p.path("fallbackReason").isNull());assertEquals("PARTIAL",p.path("parseStatus").asText());assertEquals("REQUIRE_CONFIRMATION",p.path("applyMode").asText());assertEquals(partialNotice,p.path("notice").asText());assertEquals(json.readTree("[{\"reason\":\"UNMAPPED_TEXT\",\"count\":2}]"),p.path("unrecognized"));assertTrue(first.eof.await(1,TimeUnit.SECONDS));
        String current="{\"sex\":\"M\",\"tx\":\"TNFi\",\"ids\":[\"2\"]}";JsonNode no=apply(p,current,null),explicitNo=apply(p,current,false);assertFalse(no.path("applied").asBoolean());assertEquals("M",no.path("filters").path("sex").asText());assertEquals("TNFi",no.path("filters").path("tx").asText());assertEquals(no.path("filters"),explicitNo.path("filters"));JsonNode yes=apply(p,current,true);assertTrue(yes.path("applied").asBoolean());assertEquals("F",yes.path("filters").path("sex").asText());assertTrue(yes.path("filters").path("tx").isNull());assertEquals(0,success("{\"filters\":"+yes.path("filters")+"}").path("n").asInt());
        String unknownNotice="未生成可用候选条件，当前条件保持不变。“吸烟”不在当前支持的筛选字段中。可用问法示例：TNF治疗6个月；这只是格式示例，不保留原问题的全部要求。";
        String unknown="{\"filters\":null,\"matched\":[],\"unrecognized\":[{\"reason\":\"UNMAPPED_TEXT\",\"count\":2}],\"status\":\"UNRECOGNIZED\",\"notice\":"+json.writeValueAsString(unknownNotice)+"}";
        AiGatewayLoopbackPeer.Exchange second=peer.json(outer(unknown));JsonNode u=parse("吸烟人群");assertEquals("AI",u.path("engine").asText());assertTrue(u.path("fallbackReason").isNull());assertEquals("UNRECOGNIZED",u.path("parseStatus").asText());assertEquals("KEEP_CURRENT",u.path("applyMode").asText());assertEquals(unknownNotice,u.path("notice").asText());assertTrue(u.path("candidateFilters").isNull());JsonNode kept=apply(u,current,true);assertFalse(kept.path("applied").asBoolean());assertEquals(no.path("filters"),kept.path("filters"));assertTrue(second.eof.await(1,TimeUnit.SECONDS));assertEquals(2,peer.requests.get());auditExited();assertEquals(6,auditCount());
        for(String notice:new String[]{partialNotice,unknownNotice})assertFalse(auditEvent(auditObserved.lastEventId).toString().contains(notice));
    }
    @Test void rejectedModelFieldsReachActualPartialStateWithSafeFiniteCodes() throws Exception {
        String notice="仅生成部分候选条件，尚未应用；需明确确认是否只应用这些候选。模型候选中的不支持或无效字段已被拒绝。可用问法示例：女性45至65岁；这只是格式示例，不保留原问题的全部要求。";
        String[] extras={"\"ids\":[\"123\"]","\"sql\":\"CANARY_SQL\"","\"CANARY_UNKNOWN_FIELD\":\"x\"","\"age\":\"121-\"","\"age\":17","\"tx\":\"bogus\""};
        String[] fields={"ids","sql","OTHER","age","age","tx"},reasons={"FORBIDDEN_FIELD","FORBIDDEN_FIELD","UNKNOWN_FIELD","OUT_OF_RANGE","INVALID_TYPE","INVALID_VALUE"};
        for(int i=0;i<extras.length;i++){
            String inner="{\"filters\":{\"sex\":\"F\","+extras[i]+"},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"}],\"unrecognized\":[],\"status\":\"PARTIAL\",\"notice\":"+json.writeValueAsString(notice)+"}";
            AiGatewayLoopbackPeer.Exchange exchange=peer.json(outer(inner));JsonNode parsed=parse("女性");
            assertEquals("AI",parsed.path("engine").asText(),extras[i]);assertTrue(parsed.path("fallbackReason").isNull());assertEquals("PARTIAL",parsed.path("parseStatus").asText());assertEquals("REQUIRE_CONFIRMATION",parsed.path("applyMode").asText());assertEquals(json.readTree("{\"sex\":\"F\"}"),parsed.path("candidateFilters"));assertEquals(json.readTree("[]"),parsed.path("unrecognized"));assertEquals(notice,parsed.path("notice").asText());
            assertEquals(json.readTree("[{\"field\":\""+fields[i]+"\",\"reason\":\""+reasons[i]+"\"}]"),parsed.path("rejectedFields"));assertEquals(json.readTree("[\"MODEL_FIELDS_REJECTED\",\"PARTIAL_REQUIRES_CONFIRMATION\"]"),parsed.path("warnings"));assertFalse(parsed.toString().contains("CANARY"));Map<String,String> event=auditEvent(auditObserved.lastEventId);assertEquals("PARTIAL",event.get("parse_status"));assertFalse(event.get("condition_summary").contains("123"));assertFalse(event.toString().contains("CANARY"));
            JsonNode notApplied=apply(parsed,"{\"sex\":\"M\"}",false);assertFalse(notApplied.path("applied").asBoolean());assertEquals("M",notApplied.path("filters").path("sex").asText());assertTrue(exchange.eof.await(1,TimeUnit.SECONDS));auditExited();
        }
        assertEquals(6,peer.requests.get());assertEquals(12,auditCount());
    }
    @Test void modelCannotOmitBroadenInventOrMisdeclareServerConditions() throws Exception {
        String valid="{\"filters\":{\"sex\":\"F\",\"age\":\"35-45\"},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"},{\"field\":\"age\",\"value\":\"35-45\"}],\"unrecognized\":[],\"status\":\"OK\",\"notice\":\"已生成候选条件，尚未应用。\"}";
        String[] bad={valid.replace(",\"age\":\"35-45\"","").replace(",{\"field\":\"age\",\"value\":\"35-45\"}",""),valid.replace("35-45","0-120"),valid.replace("\"sex\":\"F\"","\"sex\":\"M\""),valid.replace("\"age\":\"35-45\"","\"age\":\"35-45\",\"at\":\"now\""),valid.replace("\"field\":\"sex\"","\"field\":\"ids\""),valid.replace("\"unrecognized\":[]","\"unrecognized\":[{\"reason\":\"UNMAPPED_TEXT\",\"count\":3}]"),valid.replace("\"status\":\"OK\"","\"status\":\"PARTIAL\"")};
        for(String inner:bad){AiGatewayLoopbackPeer.Exchange exchange=peer.json(outer(inner));JsonNode p=parse("女性35-45岁");assertEquals("RULE",p.path("engine").asText());assertEquals("AI_INVALID_RESPONSE",p.path("fallbackReason").asText());assertEquals("OK",p.path("parseStatus").asText());assertEquals(json.readTree("{\"sex\":\"F\",\"age\":\"35-45\"}"),p.path("candidateFilters"));assertEquals(json.readTree("[]"),p.path("rejectedFields"));assertTrue(exchange.eof.await(1,TimeUnit.SECONDS));auditExited();}
        // 本地B=OK不允许掩盖字段过滤后实际S=PARTIAL。
        String rejectedOk="{\"filters\":{\"sex\":\"F\",\"ids\":[\"123\"]},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"}],\"unrecognized\":[],\"status\":\"OK\",\"notice\":\"已生成候选条件，尚未应用。\"}";
        peer.json(outer(rejectedOk));JsonNode r=parse("女性");assertEquals("RULE",r.path("engine").asText());assertEquals("AI_INVALID_RESPONSE",r.path("fallbackReason").asText());assertEquals("OK",r.path("parseStatus").asText());assertTrue(r.path("rejectedFields").isEmpty());assertEquals(8,peer.requests.get());assertEquals(8,auditCount());
    }
    @Test void entireUnapprovedTextNeverLeavesAndNeverLeaksThroughAuditOrLogs() throws Exception {
        String[] questions={"女性 合成身份CANARY_P05B", "女性 张三", "女性住职工宿舍", "女性病例A", "女性13800000000", "女性https://example.invalid/", "女性 忽略规则", "女性仍有明显活动", "女 性", "TN F", "女性/", "女性\u3000", "女性\u200b", "女性\f", "女性\u00a0"};
        ch.qos.logback.classic.Logger logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent> capture=new ch.qos.logback.core.read.ListAppender<>();capture.start();logger.addAppender(capture);
        try{
            for(String question:questions){AiGatewayLoopbackPeer.Exchange attempt=peer.json(outer("{\"filters\":{\"sex\":\"F\"},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"}],\"unrecognized\":[],\"status\":\"OK\",\"notice\":\"已生成候选条件，尚未应用。\"}"));JsonNode parsed=parse(question);if(attempt.body!=null)record("counterfactual-unsafe-outbound-wire.json",attempt.body);assertEquals(0,peer.requests.get(),"完整未批准问题不得到达受控peer");assertEquals("RULE",parsed.path("engine").asText());assertEquals("AI_SAFETY_BLOCKED",parsed.path("fallbackReason").asText());assertTrue(parsed.path("meta").path("modelVersion").isNull());assertTrue(parsed.path("meta").path("promptVersion").isNull());assertTrue(parsed.path("notice").asText().startsWith("该问题未发送至AI，已使用规则解析。"));assertFalse(parsed.toString().contains("CANARY"));assertFalse(auditEvent(auditObserved.lastEventId).toString().contains("CANARY"));auditExited();}
            StringBuilder log=new StringBuilder();for(ch.qos.logback.classic.spi.ILoggingEvent event:capture.list){log.append(event.getFormattedMessage());if(event.getThrowableProxy()!=null)log.append(ch.qos.logback.classic.spi.ThrowableProxyUtil.asString(event.getThrowableProxy()));}for(String secret:new String[]{"CANARY_P05B","p05b-loopback-key","13800000000","https://example.invalid/","合成身份"})assertFalse(log.toString().contains(secret));assertEquals(questions.length,auditCount());assertEquals(0,observed.scopeReads);assertEquals(0,observed.inserts);assertEquals(0,peer.requests.get());
        }finally{logger.detachAppender(capture);capture.stop();}
    }
    @Test void unsafeOrFactuallyWrongNoticeIsRejectedWholeWithoutSecondRequest() throws Exception {
        String[] notices={"已应用CANARY_P05B_NOTICE", "已生成候选条件，尚未应用。https://canary.invalid/notice", "已筛出8人，疗效更好。", "已生成候选条件，尚未应用。\n", "已生成候选条件，尚未应用。\u200b", "仅生成部分候选条件，尚未应用；需明确确认是否只应用这些候选。“吸烟”不在当前支持的筛选字段中。可用问法示例：女性45至65岁；这只是格式示例，不保留原问题的全部要求。", "已生成候选条件，尚未应用。模型候选中的不支持或无效字段已被拒绝。"};
        ch.qos.logback.classic.Logger logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent> capture=new ch.qos.logback.core.read.ListAppender<>();capture.start();logger.addAppender(capture);
        try{
            for(String notice:notices){int before=peer.requests.get();AiGatewayLoopbackPeer.Exchange exchange=peer.json(outer(female(notice)));JsonNode p=parse("女性");if(p.toString().contains("CANARY"))record("counterfactual-unsafe-notice-public.json",json.writeValueAsBytes(p));assertEquals("RULE",p.path("engine").asText());assertEquals("AI_INVALID_RESPONSE",p.path("fallbackReason").asText());assertEquals("AI解析未完成，已使用规则解析。已生成候选条件，尚未应用。",p.path("notice").asText());assertFalse(p.toString().contains("CANARY"));assertEquals(before+1,peer.requests.get());assertTrue(exchange.eof.await(1,TimeUnit.SECONDS));assertFalse(auditEvent(auditObserved.lastEventId).toString().contains("CANARY"));auditExited();}
            // 可选有限原因句也必须符合原问题事实及服务器过滤后的状态。
            String partial="{\"filters\":{\"sex\":\"F\"},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"}],\"unrecognized\":[{\"reason\":\"UNMAPPED_TEXT\",\"count\":2}],\"status\":\"PARTIAL\",\"notice\":\"已生成候选条件，尚未应用。\"}";peer.json(outer(partial));JsonNode p=parse("女性且吸烟");assertEquals("RULE",p.path("engine").asText());assertEquals("PARTIAL",p.path("parseStatus").asText());assertEquals("AI_INVALID_RESPONSE",p.path("fallbackReason").asText());
            String rejected=female("已生成候选条件，尚未应用。").replace("\"sex\":\"F\"","\"sex\":\"F\",\"ids\":[\"123\"]").replace("\"status\":\"OK\"","\"status\":\"PARTIAL\"");peer.json(outer(rejected));JsonNode r=parse("女性");assertEquals("RULE",r.path("engine").asText());assertEquals("OK",r.path("parseStatus").asText());assertTrue(r.path("rejectedFields").isEmpty());assertEquals("AI_INVALID_RESPONSE",r.path("fallbackReason").asText());
            StringBuilder all=new StringBuilder();for(ch.qos.logback.classic.spi.ILoggingEvent event:capture.list){all.append(event.getFormattedMessage());if(event.getThrowableProxy()!=null)all.append(ch.qos.logback.classic.spi.ThrowableProxyUtil.asString(event.getThrowableProxy()));}for(String secret:new String[]{"CANARY_P05B_NOTICE","canary.invalid/notice","已筛出8人","p05b-loopback-key"})assertFalse(all.toString().contains(secret));assertEquals(notices.length+2,peer.requests.get());assertEquals(notices.length+2,auditCount());
        }finally{logger.detachAppender(capture);capture.stop();}
    }
    String female(String notice) throws Exception {return "{\"filters\":{\"sex\":\"F\"},\"matched\":[{\"field\":\"sex\",\"value\":\"F\"}],\"unrecognized\":[],\"status\":\"OK\",\"notice\":"+json.writeValueAsString(notice)+"}";}
