    @Test void headerAndBodyStallsUseOneDeadlineCancelRealSocketAndRecoverCapacity() throws Exception {
        for(boolean bodyStall:new boolean[]{false,true}){
            byte[] response=bodyStall?AiGatewayLoopbackPeer.http(200,"Content-Type: application/json\r\nContent-Length: 1000\r\n",new byte[]{'{'}):new byte[0];AiGatewayLoopbackPeer.Exchange exchange=peer.reply(response);Caller caller=new Caller("女性",false);
            try{
                assertTrue(exchange.received.await(2,TimeUnit.SECONDS),"完整HTTP请求必须先触达");if(bodyStall)assertTrue(exchange.written.await(1,TimeUnit.SECONDS),"真实header/body前缀已发");
                assertTrue(caller.done.await(5500,TimeUnit.MILLISECONDS),"真实caller必须在单一budget结束");assertTrue(caller.millis()<=5500,"不能给连接/响应各开新5秒");assertTrue(caller.millis()>=3500,"deadline切点确实等过，未由peer提前释放");
                JsonNode p=caller.data();assertEquals(200,caller.response.getResponse().getStatus());assertEquals("RULE",p.path("engine").asText());assertEquals("AI_TIMEOUT",p.path("fallbackReason").asText());assertEquals("p05b-synthetic-model",p.path("meta").path("modelVersion").asText());assertTrue(exchange.eof.await(1,TimeUnit.SECONDS),"fixture close前真实peer自动EOF");networkExited();auditExited();assertEquals("RULE",auditEvent(auditObserved.lastEventId).get("engine"));
                AiGatewayLoopbackPeer.Exchange next=peer.json(outer(female("已生成候选条件，尚未应用。")));assertEquals("AI",parse("女性").path("engine").asText());assertTrue(next.eof.await(1,TimeUnit.SECONDS));networkExited();
            }finally{caller.fallbackCleanup();}
        }
        assertEquals(4,peer.requests.get());assertEquals(4,auditCount());assertNull(peer.failure.get());
    }
    @Test void realCallerInterruptCancelsBeforeNetworkDeadlineAndNeverAuditsSuccess() throws Exception {
        AiGatewayLoopbackPeer.Exchange exchange=peer.reply(new byte[0]);Caller caller=new Caller("女性",false);
        try{
            assertTrue(exchange.received.await(2,TimeUnit.SECONDS),"真实完整peer请求屏障");caller.thread.interrupt();boolean eof=exchange.eof.await(1000,TimeUnit.MILLISECONDS);long observed=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-caller.started);
            System.out.println("P05b actual cancellation observation_ms="+observed+" peer_eof="+eof+" owner_active="+networkExecutor(context.getBean(com.wenwen.ai.parse.AiParseGateway.class)).getActiveCount()+" caller_done="+(caller.done.getCount()==0)+" network_deadline_ms=4500");assertTrue(observed<3000,"观察必须明显早于独立N，不能让库timer代救");assertTrue(eof,"真实caller中断必须主动使peer EOF，不能等N或fixture close");
            assertTrue(caller.done.await(500,TimeUnit.MILLISECONDS));assertNull(caller.error.get());assertEquals(503,caller.response.getResponse().getStatus());JsonNode envelope=json.readTree(caller.response.getResponse().getContentAsByteArray());assertEquals("SERVICE_UNAVAILABLE",envelope.path("code").asText());assertTrue(envelope.path("data").isNull());assertTrue(caller.interrupted,"真实servlet caller最终interrupt应保留");networkExited();auditExited();assertEquals(0,auditCount());assertEquals(1,peer.requests.get());
            AiGatewayLoopbackPeer.Exchange next=peer.json(outer(female("已生成候选条件，尚未应用。")));assertEquals("AI",parse("女性").path("engine").asText());assertTrue(next.eof.await(1,TimeUnit.SECONDS));networkExited();assertEquals(1,auditCount());
        }finally{caller.fallbackCleanup();}
        for(String enabled:new String[]{"true","false"}){
            configure("ra.ai.gateway.enabled",enabled);long oldCount=auditCount();int oldRequests=peer.requests.get();AiGatewayLoopbackPeer.Exchange forbidden=peer.json(outer(female("已生成候选条件，尚未应用。")));Caller pre=new Caller("女性",true);
            try{assertTrue(pre.done.await(2,TimeUnit.SECONDS));assertNull(pre.error.get());assertEquals(503,pre.response.getResponse().getStatus());assertTrue(json.readTree(pre.response.getResponse().getContentAsByteArray()).path("data").isNull());assertTrue(pre.interrupted);assertEquals(oldRequests,peer.requests.get());assertEquals(oldCount,auditCount());auditExited();peer.discardUnused(forbidden);}finally{pre.fallbackCleanup();}
        }
    }
