        for(int i=0;i<questions.length;i++){String inner="{\"filters\":"+filters[i]+",\"matched\":"+matched[i]+",\"unrecognized\":[],\"status\":\"OK\",\"notice\":\"已生成候选条件，尚未应用。\"}";AiGatewayLoopbackPeer.Exchange exchange=peer.json(outer(inner));JsonNode p=parse(questions[i]);assertEquals("AI",p.path("engine").asText(),questions[i]);assertEquals(json.readTree(filters[i]),p.path("candidateFilters"));assertEquals(questions[i],json.readTree(exchange.body).path("messages").get(1).path("content").asText());assertTrue(exchange.eof.await(1,TimeUnit.SECONDS));networkExited();auditExited();}
