    @Test void actualTransportTruncationAndUnreadHttpErrorBodyStayFiniteAndReleaseOwner() throws Exception {
        ch.qos.logback.classic.Logger logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent> capture=new ch.qos.logback.core.read.ListAppender<>();capture.start();logger.addAppender(capture);
        try{
            byte[][] responses={AiGatewayLoopbackPeer.http(200,"Content-Type: application/json\r\nContent-Length: 1000\r\n","{\"CANARY_P05B_TRUNC\":1".getBytes(java.nio.charset.StandardCharsets.UTF_8)),new byte[0]};
            for(byte[] response:responses){int before=peer.requests.get();AiGatewayLoopbackPeer.Exchange exchange=peer.closeAfterWrite(response);JsonNode p=parse("女性");assertTrue(exchange.received.await(1,TimeUnit.SECONDS));assertTrue(exchange.written.await(1,TimeUnit.SECONDS));assertEquals("RULE",p.path("engine").asText());assertEquals("AI_IO_ERROR",p.path("fallbackReason").asText());assertEquals("p05b-synthetic-model",p.path("meta").path("modelVersion").asText());assertEquals(before+1,peer.requests.get());networkExited();auditExited();assertFalse(p.toString().contains("CANARY"));}
            AiGatewayLoopbackPeer.Exchange error=peer.reply(AiGatewayLoopbackPeer.http(503,"Retry-After: 0\r\nContent-Length: 1000000\r\n","CANARY_P05B_HTTP_BODY".getBytes(java.nio.charset.StandardCharsets.UTF_8)));JsonNode p=parse("女性");assertEquals("AI_HTTP_ERROR",p.path("fallbackReason").asText());assertTrue(error.eof.await(1,TimeUnit.SECONDS));networkExited();auditExited();assertEquals(3,peer.requests.get());assertEquals(3,auditCount());
            StringBuilder all=new StringBuilder();for(ch.qos.logback.classic.spi.ILoggingEvent event:capture.list){all.append(event.getFormattedMessage());if(event.getThrowableProxy()!=null)all.append(ch.qos.logback.classic.spi.ThrowableProxyUtil.asString(event.getThrowableProxy()));}assertFalse(all.toString().contains("CANARY_P05B_TRUNC"));assertFalse(all.toString().contains("CANARY_P05B_HTTP_BODY"));assertFalse(all.toString().contains("p05b-loopback-key"));
            AiGatewayLoopbackPeer.Exchange recovered=peer.json(outer(female("已生成候选条件，尚未应用。")));assertEquals("AI",parse("女性").path("engine").asText());assertTrue(recovered.eof.await(1,TimeUnit.SECONDS));networkExited();assertEquals(4,peer.requests.get());assertEquals(4,auditCount());
        }finally{logger.detachAppender(capture);capture.stop();}
    }
    void record(String name,byte[] value) throws Exception {String directory=System.getenv("RA_P05B_EVIDENCE_DIR");if(directory!=null)java.nio.file.Files.write(java.nio.file.Paths.get(directory).resolve(name),value);}
    Set<String> keys(JsonNode node){Set<String> keys=new TreeSet<>();node.fieldNames().forEachRemaining(keys::add);return keys;}
